    k = 2
    n = len(problem_qubits)

    # Compute the vertex cover predicate
    for i in range(n):
        qc.cx(problem_qubits[i], ancilla_qubits[0])

    for i in range(n):
        for j in range(i + 1, n):
            qc.ccx(problem_qubits[i], problem_qubits[j], ancilla_qubits[1])

    # Apply the phase oracle
